#!/usr/bin/env python3
from pathlib import Path
import sys

path = Path(sys.argv[1]) if len(sys.argv) > 1 else Path('droiddeck-launcher/ConsoleWindow.cpp')
text = path.read_text()


def replace_once(old: str, new: str, label: str) -> None:
    global text
    if new in text:
        return
    if old not in text:
        raise SystemExit(f'UI patch failed: {label} pattern not found')
    text = text.replace(old, new, 1)

replace_once(
'''    resize(1280, 800);\n    setMinimumSize(960, 600);''',
'''    // DroidDeck renders a landscape surface with a virtual gamepad over the edges.\n    // Keep the launcher flexible instead of forcing a desktop-sized minimum window.\n    resize(1280, 720);\n    setMinimumSize(640, 360);''',
'window geometry')

replace_once('''            font-size:15px;''', '''            font-size:18px;''', 'base font')
replace_once('''        QLabel#pageTitle { font-size:26px; font-weight:900; }\n        QLabel#pageDescription { color:#8190a3; font-size:12px; }''',
'''        QLabel#pageTitle { font-size:31px; font-weight:900; }\n        QLabel#pageDescription { color:#a5b3c5; font-size:15px; }''', 'page typography')
replace_once('''        QLabel#settingName { font-size:15px; font-weight:800; }\n        QLabel#settingDescription { color:#728398; font-size:10px; }''',
'''        QLabel#settingName { font-size:19px; font-weight:850; }\n        QLabel#settingDescription { color:#8d9caf; font-size:13px; }''', 'settings typography')
replace_once('''        QLabel#errorSummary { font-size:23px; font-weight:900; }\n        QPlainTextEdit#errorDetails { background:#070b10; border:1px solid #29364a; font-family:monospace; font-size:11px; }''',
'''        QLabel#errorSummary { font-size:30px; font-weight:900; }\n        QPlainTextEdit#errorDetails { background:#070b10; border:1px solid #29364a; border-radius:12px; padding:10px; font-family:monospace; font-size:14px; }''', 'error typography')
replace_once('''        QListWidget#browserList::item {\n            color:#c0ccda; padding:14px 16px; margin:3px; border-radius:10px; border:1px solid transparent;\n        }''',
'''        QListWidget#browserList::item {\n            color:#d5dfeb; padding:19px 20px; margin:4px; border-radius:12px; border:1px solid transparent;\n            font-size:18px; font-weight:700;\n        }''', 'browser rows')
replace_once('''        QListWidget#sections {\n            background:#0b111c; border:1px solid #182235; border-radius:18px; padding:8px;\n            outline:0;\n        }\n        QListWidget#sections::item {\n            color:#8797aa; padding:15px 13px; margin:3px; border-radius:11px; font-weight:700;\n        }\n        QListWidget#sections::item:selected {\n            color:white; background:#1769ff; border-left:4px solid #8ee7ff;\n        }''',
'''        QListWidget#sections {\n            background:#0b111c; border:1px solid #182235; border-radius:14px; padding:4px;\n            outline:0;\n        }\n        QListWidget#sections::item {\n            color:#8797aa; padding:11px 16px; margin:2px; border-radius:9px; font-size:14px; font-weight:800;\n        }\n        QListWidget#sections::item:selected {\n            color:white; background:#1769ff; border-bottom:3px solid #8ee7ff;\n        }''', 'top tabs style')

old_shell = '''QWidget *ConsoleWindow::buildShellPage()\n{\n    auto *page = new QWidget();\n    auto *outer = new QVBoxLayout(page);\n    outer->setContentsMargins(20, 16, 20, 14);\n    outer->setSpacing(12);\n\n    auto *header = new QHBoxLayout();\n    header->setSpacing(12);\n    auto *mark = new QLabel(QStringLiteral("K5"));\n    mark->setObjectName(QStringLiteral("brandMark"));\n    mark->setAlignment(Qt::AlignCenter);\n    header->addWidget(mark);\n\n    auto *brand = new QVBoxLayout();\n    brand->setSpacing(1);\n    auto *title = new QLabel(QStringLiteral("KytyPS5"));\n    title->setObjectName(QStringLiteral("brandTitle"));\n    auto *subtitle = new QLabel(QStringLiteral("PS5 translation layer  ·  DroidDeck / FEX"));\n    subtitle->setObjectName(QStringLiteral("brandSubtitle"));\n    brand->addWidget(title);\n    brand->addWidget(subtitle);\n    header->addLayout(brand);\n    header->addStretch(1);\n\n    header->addWidget(makePill(QStringLiteral("KYTY CORE  ·  VULKAN"), QStringLiteral("corePill")));\n    m_controllerLabel = makePill(QStringLiteral("PAD  DETECTING"), QStringLiteral("controllerPill"));\n    m_controllerLabel->setProperty("connected", false);\n    header->addWidget(m_controllerLabel);\n    outer->addLayout(header);\n\n    auto *body = new QHBoxLayout();\n    body->setSpacing(14);\n\n    m_sections = new QListWidget();\n    m_sections->setObjectName(QStringLiteral("sections"));\n    m_sections->setFixedWidth(195);\n    m_sections->setFocusPolicy(Qt::NoFocus);\n    m_sections->addItems({\n        QStringLiteral("▦   LIBRARY"),\n        QStringLiteral("◇   GRAPHICS"),\n        QStringLiteral("●   SYSTEM"),\n        QStringLiteral("✦   CONTROLLER"),\n        QStringLiteral("!   DEBUG"),\n        QStringLiteral("…   EXPERT")\n    });\n    m_sections->setCurrentRow(0);\n    body->addWidget(m_sections);\n\n    m_sectionStack = new QStackedWidget();\n    m_sectionStack->addWidget(buildLibraryPage());\n    m_sectionStack->addWidget(buildGraphicsPage());\n    m_sectionStack->addWidget(buildSystemPage());\n    m_sectionStack->addWidget(buildControllerPage());\n    m_sectionStack->addWidget(buildDebugPage());\n    m_sectionStack->addWidget(buildExpertPage());\n    body->addWidget(m_sectionStack, 1);\n    outer->addLayout(body, 1);\n\n    m_statusLabel = new QLabel(QStringLiteral("Ready"));\n    m_statusLabel->setObjectName(QStringLiteral("statusBar"));\n    outer->addWidget(m_statusLabel);\n\n    m_hintLabel = new QLabel();\n    m_hintLabel->setObjectName(QStringLiteral("hintBar"));\n    m_hintLabel->setAlignment(Qt::AlignCenter);\n    outer->addWidget(m_hintLabel);\n\n    connect(m_sections, &QListWidget::currentRowChanged, this, [this](int row) {\n        if (row < 0 || row >= m_sectionStack->count()) return;\n        m_lastSection = row;\n        m_sectionStack->setCurrentIndex(row);\n        updateHints();\n        QTimer::singleShot(0, this, [this, row] {\n            if (row == 0) focusLibraryButton(std::max(0, focusedLibraryIndex()));\n            else focusFirstControl();\n        });\n    });\n\n    return page;\n}\n'''
new_shell = '''QWidget *ConsoleWindow::buildShellPage()\n{\n    auto *page = new QWidget();\n    auto *outer = new QVBoxLayout(page);\n    // Keep all important controls away from DroidDeck's virtual D-pad / ABXY zones.\n    outer->setContentsMargins(150, 14, 150, 14);\n    outer->setSpacing(9);\n\n    auto *header = new QHBoxLayout();\n    header->setSpacing(10);\n    auto *mark = new QLabel(QStringLiteral("K5"));\n    mark->setObjectName(QStringLiteral("brandMark"));\n    mark->setAlignment(Qt::AlignCenter);\n    header->addWidget(mark);\n\n    auto *brand = new QVBoxLayout();\n    brand->setSpacing(0);\n    auto *title = new QLabel(QStringLiteral("KytyPS5"));\n    title->setObjectName(QStringLiteral("brandTitle"));\n    auto *subtitle = new QLabel(QStringLiteral("DroidDeck console mode"));\n    subtitle->setObjectName(QStringLiteral("brandSubtitle"));\n    brand->addWidget(title);\n    brand->addWidget(subtitle);\n    header->addLayout(brand);\n    header->addStretch(1);\n\n    m_controllerLabel = makePill(QStringLiteral("PAD  DETECTING"), QStringLiteral("controllerPill"));\n    m_controllerLabel->setProperty("connected", false);\n    header->addWidget(m_controllerLabel);\n    outer->addLayout(header);\n\n    // Horizontal tabs are intentionally kept out of the left overlay area.\n    m_sections = new QListWidget();\n    m_sections->setObjectName(QStringLiteral("sections"));\n    m_sections->setFlow(QListView::LeftToRight);\n    m_sections->setWrapping(false);\n    m_sections->setHorizontalScrollBarPolicy(Qt::ScrollBarAlwaysOff);\n    m_sections->setVerticalScrollBarPolicy(Qt::ScrollBarAlwaysOff);\n    m_sections->setFixedHeight(54);\n    m_sections->setFocusPolicy(Qt::NoFocus);\n    m_sections->addItems({\n        QStringLiteral("LIBRARY"),\n        QStringLiteral("GRAPHICS"),\n        QStringLiteral("SYSTEM"),\n        QStringLiteral("CONTROLLER"),\n        QStringLiteral("DEBUG"),\n        QStringLiteral("EXPERT")\n    });\n    m_sections->setCurrentRow(0);\n    outer->addWidget(m_sections);\n\n    m_sectionStack = new QStackedWidget();\n    m_sectionStack->addWidget(buildLibraryPage());\n    m_sectionStack->addWidget(buildGraphicsPage());\n    m_sectionStack->addWidget(buildSystemPage());\n    m_sectionStack->addWidget(buildControllerPage());\n    m_sectionStack->addWidget(buildDebugPage());\n    m_sectionStack->addWidget(buildExpertPage());\n    outer->addWidget(m_sectionStack, 1);\n\n    // Status/hints are still updated internally, but are hidden because DroidDeck's\n    // bottom overlay occupies exactly the same screen region.\n    m_statusLabel = new QLabel(QStringLiteral("Ready"));\n    m_statusLabel->setObjectName(QStringLiteral("statusBar"));\n    m_statusLabel->hide();\n    m_hintLabel = new QLabel();\n    m_hintLabel->setObjectName(QStringLiteral("hintBar"));\n    m_hintLabel->hide();\n\n    connect(m_sections, &QListWidget::currentRowChanged, this, [this](int row) {\n        if (row < 0 || row >= m_sectionStack->count()) return;\n        m_lastSection = row;\n        m_sectionStack->setCurrentIndex(row);\n        updateHints();\n        QTimer::singleShot(0, this, [this, row] {\n            if (row == 0) focusLibraryButton(std::max(0, focusedLibraryIndex()));\n            else focusFirstControl();\n        });\n    });\n\n    return page;\n}\n'''
replace_once(old_shell, new_shell, 'shell layout')

old_browser = '''    auto *layout = new QVBoxLayout(page);\n    layout->setContentsMargins(24, 18, 24, 16);\n    layout->setSpacing(12);'''
new_browser = '''    auto *layout = new QVBoxLayout(page);\n    // Built-in browser uses the same DroidDeck-safe center column.\n    layout->setContentsMargins(150, 18, 150, 18);\n    layout->setSpacing(10);'''
replace_once(old_browser, new_browser, 'browser safe area')

old_error = '''QWidget *ConsoleWindow::buildErrorPage()\n{\n    auto *page = new QWidget();\n    auto *outer = new QVBoxLayout(page);\n    outer->setContentsMargins(40, 28, 40, 28);\n    outer->addStretch(1);\n\n    auto *panel = new QFrame();\n    panel->setObjectName(QStringLiteral("errorPanel"));\n    panel->setMaximumWidth(980);\n    auto *layout = new QVBoxLayout(panel);\n    layout->setContentsMargins(24, 22, 24, 22);\n    layout->setSpacing(12);\n\n    m_errorTitle = new QLabel(QStringLiteral("KYTY CORE ERROR"));\n    m_errorTitle->setObjectName(QStringLiteral("errorTitle"));\n    m_errorSummary = new QLabel();\n    m_errorSummary->setObjectName(QStringLiteral("errorSummary"));\n    m_errorSummary->setWordWrap(true);\n    auto *desc = new QLabel(QStringLiteral("The launcher kept the error inside this window. Full core output is shown below."));\n    desc->setObjectName(QStringLiteral("pageDescription"));\n    desc->setWordWrap(true);\n    m_errorDetails = new QPlainTextEdit();\n    m_errorDetails->setObjectName(QStringLiteral("errorDetails"));\n    m_errorDetails->setReadOnly(true);\n    m_errorDetails->setMinimumHeight(300);\n    m_errorBack = new QPushButton(QStringLiteral("B   Back to library"));\n    m_errorBack->setObjectName(QStringLiteral("primaryButton"));\n    m_errorBack->setFocusPolicy(Qt::StrongFocus);\n\n    layout->addWidget(m_errorTitle);\n    layout->addWidget(m_errorSummary);\n    layout->addWidget(desc);\n    layout->addWidget(m_errorDetails, 1);\n    layout->addWidget(m_errorBack, 0, Qt::AlignRight);\n\n    auto *center = new QHBoxLayout();\n    center->addStretch(1);\n    center->addWidget(panel, 1);\n    center->addStretch(1);\n    outer->addLayout(center, 1);\n    outer->addStretch(1);\n\n    connect(m_errorBack, &QPushButton::clicked, this, [this] { closeErrorPage(); });\n    return page;\n}\n'''
new_error = '''QWidget *ConsoleWindow::buildErrorPage()\n{\n    auto *page = new QWidget();\n    auto *outer = new QVBoxLayout(page);\n    // The old page used stretch + panel + stretch horizontally, which gave the\n    // actual error card only about one third of the screen. Keep a fixed safe\n    // center column instead so text remains readable between virtual controls.\n    outer->setContentsMargins(280, 28, 280, 28);\n    outer->setSpacing(12);\n\n    auto *panel = new QFrame();\n    panel->setObjectName(QStringLiteral("errorPanel"));\n    auto *layout = new QVBoxLayout(panel);\n    layout->setContentsMargins(28, 24, 28, 24);\n    layout->setSpacing(14);\n\n    m_errorTitle = new QLabel(QStringLiteral("KYTY CORE ERROR"));\n    m_errorTitle->setObjectName(QStringLiteral("errorTitle"));\n    m_errorSummary = new QLabel();\n    m_errorSummary->setObjectName(QStringLiteral("errorSummary"));\n    m_errorSummary->setWordWrap(true);\n\n    m_errorBack = new QPushButton(QStringLiteral("B   BACK TO LIBRARY"));\n    m_errorBack->setObjectName(QStringLiteral("primaryButton"));\n    m_errorBack->setMinimumHeight(56);\n    m_errorBack->setFocusPolicy(Qt::StrongFocus);\n\n    auto *desc = new QLabel(QStringLiteral("Core log"));\n    desc->setObjectName(QStringLiteral("pageDescription"));\n    m_errorDetails = new QPlainTextEdit();\n    m_errorDetails->setObjectName(QStringLiteral("errorDetails"));\n    m_errorDetails->setReadOnly(true);\n    m_errorDetails->setMinimumHeight(220);\n\n    layout->addWidget(m_errorTitle);\n    layout->addWidget(m_errorSummary);\n    layout->addWidget(m_errorBack);\n    layout->addWidget(desc);\n    layout->addWidget(m_errorDetails, 1);\n    outer->addWidget(panel, 1);\n\n    connect(m_errorBack, &QPushButton::clicked, this, [this] { closeErrorPage(); });\n    return page;\n}\n'''
replace_once(old_error, new_error, 'error page')

# Make the settings content denser vertically but much easier to read/focus.
replace_once('''        layout->setContentsMargins(16, 11, 14, 11);\n        layout->setSpacing(18);''',
'''        layout->setContentsMargins(18, 14, 16, 14);\n        layout->setSpacing(20);''', 'focus row spacing')

path.write_text(text)
print(f'patched DroidDeck-safe UI: {path}')
